sp_header_footer.client_script:
function($rootScope, $scope, snRecordWatcher, spUtil,
         $location, $uibModal, cabrillo, $timeout,
         $window, i18n, spAriaUtil, $element, $injector) {

    // Original header variables
    $scope.logoText = $scope.data.logoText || '';
    $scope.collapse = true;

    // Search functionality
    $scope.searchTerm = '';

    $scope.submitSearch = function() {
        var query = ($scope.searchTerm || '').trim();

        if (!query) {
            return;
        }

        $rootScope.$broadcast('fm.search', {
            query: query
        });
    };

    $scope.clearSearch = function() {
        $scope.searchTerm = '';

        $rootScope.$broadcast('fm.search', {
            query: ''
        });
    };

    // Original avatar functionality
    $scope.avatarProfile = {
        userID: $window.NOW.user_id,
        name: $window.NOW.user_display_name,
        initials: $window.NOW.user_initials
    };

    if ($window.NOW.user_avatar) {
        $scope.avatarProfile.avatar = $window.NOW.user_avatar;
    }

    if (cabrillo.isNative()) {
        $scope.isNative = true;
    }

    // Original popup functionality
    $scope.openPopUp = function() {
        $scope.modalInstance = $uibModal.open({
            templateUrl: 'sp-modal',
            scope: $scope
        });
    };

    // Login popup
    $scope.openLogin = function() {
        var loginWidget = $injector.get('spUtil');

        if ($scope.data.loginWidget) {
            loginWidget.addInfoMessage(
                i18n.getMessage('Please login to continue')
            );
        }
    };

    // Responsive avatar handling
    var nav = document.getElementById('responsiveNav');

    function isMDScreenSize() {
        return $window.matchMedia('(max-width: 992px)').matches;
    }

    $scope.showSMAvatar = isMDScreenSize();
    $scope.showAvatar = !isMDScreenSize();

    $scope.isAgentChatConfigured =
        typeof g_has_agent_chat_config !== 'undefined' &&
        g_has_agent_chat_config;

    function updateResponsiveClasses(width) {
        if (!nav) {
            return;
        }

        var isMobile = width <= 992;

        if (isMobile) {
            nav.classList.add('responsive-tablet');
            nav.classList.remove('responsive-desktop');
        } else {
            nav.classList.add('responsive-desktop');
            nav.classList.remove('responsive-tablet');
        }

        $scope.$applyAsync(function() {
            $scope.showSMAvatar = isMobile;
            $scope.showAvatar = !isMobile;
        });
    }

    if (nav) {
        updateResponsiveClasses(nav.getBoundingClientRect().width);
    }

    var observer = null;

    if (nav && $window.ResizeObserver) {
        observer = new $window.ResizeObserver(function(entries) {
            if (entries.length) {
                updateResponsiveClasses(entries[0].contentRect.width);
            }
        });

        observer.observe(nav);
    }

    // Original avatar change listener
    var avatarListener = $rootScope.$on(
        'sp.avatar_changed',
        function(event, newAvatar) {
            if (newAvatar) {
                $scope.avatarProfile.avatar = newAvatar;
            }
        }
    );

    // Homepage detection
    $scope.isHomepage =
        $location.path() === '/' ||
        $location.path() === '';

    // Accessibility
    $timeout(function() {
        if (spAriaUtil && spAriaUtil.initDropdownKeyboardNav) {
            spAriaUtil.initDropdownKeyboardNav($element);
        }
    });

    // Cleanup
    $scope.$on('$destroy', function() {
        if (observer) {
            observer.disconnect();
        }

        avatarListener();
    });
}

sp_header_footer.css:
/* ========================================
   FILE MANAGER HEADER
======================================== */

.fm-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    min-height: 64px !important;
    height: 64px !important;
    padding: 0 20px;
    background: #FFFFFF !important;
    border: none !important;
    border-bottom: 1px solid #D7E2E7 !important;
    border-radius: 0 !important;
    margin: 0 !important;
    box-shadow: 0 1px 4px rgba(23,53,74,.05);
}

/* Logo and search section */

.fm-navbar .navbar-header {
    display: flex !important;
    align-items: center;
    float: none !important;
    flex: 1 1 auto;
    width: auto;
    min-width: 0;
    height: 64px;
    min-height: 64px;
    gap: 20px;
}

/* Logo */

.fm-navbar .navbar-brand {
    display: flex !important;
    align-items: center;
    flex: 0 0 auto;
    height: 64px !important;
    padding: 0 !important;
    margin: 0 !important;
    color: #17354A !important;
    font-size: 21px;
    font-weight: 600;
    white-space: nowrap;
}

.fm-navbar .navbar-brand img {
    max-height: 38px !important;
    max-width: 170px;
    width: auto;
    margin: 0 !important;
    top: auto !important;
    transform: none !important;
}

/* Search */

.fm-search-form {
    display: flex !important;
    align-items: center;
    flex: 1 1 500px;
    width: 100%;
    max-width: none !important;
    min-width: 180px;
    height: 42px;
    margin: 0 15px;
    padding: 0 12px;
    background: #F1F7F8;
    border: 1px solid #B9CFD9;
    border-radius: 8px;
    transition: .2s ease;
}

.fm-search-form:focus-within {
    background: #FFFFFF;
    border-color: #0787A6;
    box-shadow: 0 0 0 3px rgba(7,135,166,.10);
}

.fm-search-input {
    flex: 1 1 auto;
    width: 100%;
    min-width: 0;
    height: 100%;
    border: none !important;
    outline: none !important;
    background: transparent !important;
    box-shadow: none !important;
    font-size: 14px;
    color: #17354A;
}

.fm-search-icon {
    color: #0787A6;
    margin-right: 10px;
}

.fm-search-clear,
.fm-search-submit {
    border: none;
    background: transparent;
    color: #526879;
    cursor: pointer;
}

/* Existing profile, menu and language */

.fm-navbar .navbar-right {
    display: flex !important;
    align-items: center;
    flex: 0 0 auto;
    float: none !important;
    min-height: 64px;
    padding: 0 !important;
}

.fm-navbar .navbar-nav {
    display: flex;
    align-items: center;
    margin: 0;
}

.fm-navbar .nav > li > a {
    color: #17354A !important;
    padding: 15px 12px;
}

.fm-navbar .nav > li > a:hover {
    background: #F1F7F8 !important;
    color: #0787A6 !important;
}

/* Profile dropdown */

.fm-navbar .navbar-avatar {
    display: inline-flex;
    align-items: center;
    vertical-align: middle;
    margin-right: 6px;
}

.fm-navbar .dropdown-menu {
    z-index: 1050;
    min-width: 160px;
    background: #FFFFFF;
    border: 1px solid #D7E2E7;
    border-radius: 8px;
    box-shadow: 0 5px 18px rgba(23,53,74,.12);
}

.fm-navbar .dropdown-menu > li > a {
    padding: 10px 16px;
    color: #17354A;
}

.fm-navbar .dropdown-menu > li > a:hover {
    background: #E5F5F9;
    color: #0787A6;
}

/* Tablet and mobile */

@media (max-width: 992px) {

    .fm-navbar {
        display: block !important;
        height: auto !important;
        min-height: 64px !important;
        padding: 0;
    }

    .fm-navbar .navbar-header {
        display: flex !important;
        flex-wrap: wrap;
        width: 100%;
        height: auto;
        min-height: 64px;
        padding: 8px 14px;
        gap: 10px;
    }

    .fm-navbar .navbar-brand {
        height: 42px !important;
    }

    .fm-search-form {
        order: 3;
        flex: 1 0 100%;
        width: 100%;
        margin: 0;
        height: 40px;
    }

    .fm-navbar .navbar-toggle {
        display: block;
        margin: 5px 0 5px auto;
    }

    .fm-navbar .navbar-collapse {
        width: 100%;
        background: #FFFFFF;
    }

    .fm-navbar .navbar-right {
        display: block !important;
        min-height: auto;
    }

    .fm-navbar .navbar-nav {
        display: block;
    }
}

sp_header_footer.link:
function(scope, element) {

    var KEY = {
        TAB: 9,
        ESC: 27
    };

    var navbarContainer = $('#sp-nav-bar');
    var navbarToggle = element.find('.navbar-toggle');

    function isMDScreenSize() {
        return window.matchMedia('(max-width: 992px)').matches;
    }

    // Close mobile menu
    function closeMobileMenu() {
        if (isMDScreenSize() &&
            navbarContainer.hasClass('in')) {
            navbarContainer.collapse('hide');
        }
    }

    // Focus first navigation link when menu opens
    navbarContainer.on(
        'shown.bs.collapse.fmHeader',
        function() {
            $('a:visible', navbarContainer).first().focus();
        }
    );

    // Escape key
    element.on('keyup.fmHeader', function(event) {
        if (event.which === KEY.ESC) {
            closeMobileMenu();

            if (navbarToggle.length) {
                navbarToggle.focus();
            }
        }
    });

    // Close menu after selecting a navigation link
    element.on(
        'click.fmHeader',
        '.navbar-collapse.in a',
        function() {
            closeMobileMenu();
        }
    );

    // Outside click
    function outsideClickHandler(event) {
        if (!isMDScreenSize()) {
            return;
        }

        var target = $(event.target);

        if (
            target.closest('#sp-nav-bar').length === 0 &&
            target.closest('.navbar-toggle').length === 0
        ) {
            closeMobileMenu();
        }
    }

    $(document).on(
        'click.fmHeaderOutside',
        outsideClickHandler
    );

    // Keyboard navigation
    navbarContainer.on(
        'keydown.fmHeader',
        'a',
        function(event) {
            if (event.which === KEY.ESC) {
                closeMobileMenu();

                if (navbarToggle.length) {
                    navbarToggle.focus();
                }
            }
        }
    );

    // Cleanup
    scope.$on('$destroy', function() {
        navbarContainer.off('.fmHeader');
        element.off('.fmHeader');

        $(document).off(
            'click.fmHeaderOutside',
            outsideClickHandler
        );
    });
}

sp_header_footer.script:
(function () {

    data.connect_support_queue_id = $sp.getValue('sp_chat_queue');
    data.login_page = $sp.getValue('login_page');
    data.profileBtnMsg = gs.getMessage('User options');
    data.toggleMsg = gs.getMessage('Toggle navigation');

    var menu = $sp.getValue('sp_rectangle_menu');

    data.menu = menu ? $sp.getWidgetFromInstance(menu) : null;

    data.hasMenuItems = false;
    data.hasLogin = false;

    if (data.menu && data.menu.data &&
        data.menu.data.menu) {

        data.menu.data.replace = true;

        var items = data.menu.data.menu.items || [];

        data.hasMenuItems = items.length > 0;

        for (var i = 0; i < items.length; i++) {

            var item = items[i];

            if (item.type == 'page' &&
                item.sp_page == data.login_page) {

                data.hasLogin = true;
            }
        }
    }

    data.langSelector = '';

    try {
        data.langSelector = $sp.getWidget('sp-lang-selector');
    } catch (e) {
        gs.warn('Language selector widget unavailable: ' + e.message);
    }

    data.loginWidget = $sp.getWidgetFromInstance('login-modal');

})();
